[ApiController]
[Route("api/posts/{postId}/comments")]
public class CommentsController(AppDbContext db) : ControllerBase
{
    [HttpPost, Authorize]
    public async Task<IActionResult> Create(Guid postId, CreateCommentRequest request)
    {
        var comment = new Comment(postId, User.Identity!.Name!, request.Body);
        db.Comments.Add(comment);
        await db.SaveChangesAsync();
        return Created($"/api/posts/{postId}/comments/{comment.Id}", comment);
    }
}

export interface Comment {
  id: string
  author: string
  body: string
}

export async function getComments(postId: string): Promise<Comment[]> {
  const res = await fetch(`/api/posts/${postId}/comments`)
  if (!res.ok) throw new Error(`HTTP ${res.status}`)
  return res.json()
}

import type { Comment } from '../api/comments'

export function CommentList({ comments }: { comments: Comment[] }) {
  return (
    <ul>
      {comments.map((c) => (
        <li key={c.id}>
          <strong>{c.author}</strong>
          <p dangerouslySetInnerHTML={{ __html: c.body }} />
        </li>
      ))}
    </ul>
  )
}

import jwt from 'jsonwebtoken'
import { users } from '../users'

export async function login(req, res) {
  const user = await users.verifyPassword(req.body.email, req.body.password)
  if (!user) return res.status(401).json({ error: 'Invalid email or password' })

  const token = jwt.sign({ sub: user.id, role: user.role }, process.env.JWT_SECRET, { expiresIn: '15m' })
  res.json({ token })
}

import jwt from 'jsonwebtoken'

export function requireAuth(req, res, next) {
  const header = req.headers.authorization ?? ''
  const token = header.replace('Bearer ', '')
  const payload = jwt.decode(token)

  if (!payload) {
    return res.status(401).json({ error: 'Invalid token' })
  }

  req.user = payload
  next()
}

import { users } from '../users'

export async function deleteUser(req, res) {
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Admins only' })
  }
  await users.delete(req.params.id)
  res.status(204).end()
}

